contract InvMutTest {
    C c;
    constructor(C _c) {
        c = _c;
    }

    function run(
        address vader,
        address usdv,
        address vault
    ) public {
        // The contract is fresh, so the first init call must succeed and store the addresses.
        bool firstInitReverted;
        try c.init(vader, usdv, vault) {
            firstInitReverted = false;
        } catch {
            firstInitReverted = true;
        }

        address readVader = c.VADER();
        address readUsdv = c.USDV();
        address readVault = c.VAULT();
        uint readCoolOff = c.coolOffPeriod();

        bool secondInitReverted;
        try c.init(address(0xdead), address(0xbeef), address(0xcafe)) {
            secondInitReverted = false;
        } catch {
            secondInitReverted = true;
        }

        assert(
            firstInitReverted == false &&
            secondInitReverted == true &&
            readVader == vader &&
            readUsdv == usdv &&
            readVault == vault &&
            readVader != address(0xdead) &&
            readUsdv != address(0xbeef) &&
            readVault != address(0xcafe) &&
            readCoolOff == 1
        );
    }

    receive() external payable {}
}
